_review_embeddings = save_umap_tsne_run
def save_umap_tsne_run(**kwargs):
    root = Path(kwargs['paths']['REPORTS_DIR'])
    before = {str(p.relative_to(root)):p.read_bytes() for p in root.rglob('*') if p.is_file() and 'latest' in p.name}
    try:
        return _review_embeddings(**kwargs)
    except Exception as exc:
        for p in root.rglob('*'):
            if p.is_file() and str(p.relative_to(root)) not in before and 'latest' in p.name:
                p.unlink()
        for relative, data in before.items():
            target = root / relative
            target.parent.mkdir(parents=True, exist_ok=True)
            target.write_bytes(data)
        raise RuntimeError('Publication aborted with retained cause') from exc

